'use client'

import { Menu } from 'lucide-react'
import { Fragment, useState, type ReactNode } from 'react'

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '../../components/ui/breadcrumb'
import { Button } from '../../components/ui/button'
import { Dialog, DialogContent, DialogTitle } from '../../components/ui/dialog'
import { Separator } from '../../components/ui/separator'

export type AppShellCrumb = {
  label: ReactNode
  /** Renders a native anchor. Omit on the current, final step. */
  href?: string
}

export type AppShell01Props = {
  /**
   * The navigation rendered in the desktop rail and in the mobile sheet. Pass
   * nodes rather than a route table: the block never imports a router.
   */
  navigation: ReactNode
  /** The accessible name for the navigation regions and the sheet trigger. */
  navigationLabel: string
  /** The brand or product mark at the top of the rail and the sheet. */
  brand?: ReactNode
  /** The trail shown in the top bar. */
  breadcrumbs?: AppShellCrumb[]
  /** Actions at the end of the top bar, e.g. an account menu. */
  actions?: ReactNode
  /** A slot above the navigation, e.g. a workspace switcher. */
  railHeader?: ReactNode
  /** A slot below the navigation, e.g. a user menu. */
  railFooter?: ReactNode
  children: ReactNode
}

/**
 * An application shell.
 *
 * It owns the frame every application screen repeats: a fixed rail from the
 * `lg` breakpoint up, a top bar with a breadcrumb trail and actions, and a
 * left-anchored Dialog sheet that carries the same navigation on narrow
 * screens. The navigation and the content are slots, so the app keeps its own
 * links, router and data. The block fetches nothing and imports no router.
 */
export function AppShell01({
  navigation,
  navigationLabel,
  brand,
  breadcrumbs,
  actions,
  railHeader,
  railFooter,
  children,
}: AppShell01Props) {
  const [navOpen, setNavOpen] = useState(false)

  return (
    <div className="bg-background text-foreground flex min-h-svh w-full">
      <aside className="border-border hidden w-64 shrink-0 flex-col border-r lg:flex">
        {brand ? <div className="flex h-14 items-center px-4">{brand}</div> : null}
        <Separator />
        {railHeader ? <div className="p-4">{railHeader}</div> : null}
        <nav aria-label={navigationLabel} className="flex-1 overflow-y-auto p-4">
          {navigation}
        </nav>
        {railFooter ? (
          <>
            <Separator />
            <div className="p-4">{railFooter}</div>
          </>
        ) : null}
      </aside>

      <div className="flex min-w-0 flex-1 flex-col">
        <header className="border-border flex h-14 items-center gap-3 border-b px-4">
          <Dialog open={navOpen} onOpenChange={setNavOpen}>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="lg:hidden"
              aria-label={navigationLabel}
              onClick={() => setNavOpen(true)}
            >
              <Menu className="size-5" />
            </Button>
            <DialogContent side="left" className="w-72 gap-0 p-0">
              <DialogTitle className="sr-only">{navigationLabel}</DialogTitle>
              <div className="flex h-full flex-col p-4">
                {brand ? <div className="mb-4">{brand}</div> : null}
                {railHeader ? <div className="mb-4">{railHeader}</div> : null}
                <nav aria-label={navigationLabel} className="flex-1 overflow-y-auto">
                  {navigation}
                </nav>
                {railFooter ? <div className="mt-4">{railFooter}</div> : null}
              </div>
            </DialogContent>
          </Dialog>

          {breadcrumbs?.length ? (
            <Breadcrumb>
              <BreadcrumbList>
                {breadcrumbs.map((crumb, index) => {
                  const last = index === breadcrumbs.length - 1
                  return (
                    // Positional, for the same reason as the other blocks.
                    <Fragment key={index}>
                      {index > 0 ? <BreadcrumbSeparator /> : null}
                      <BreadcrumbItem>
                        {last || !crumb.href ? (
                          <BreadcrumbPage>{crumb.label}</BreadcrumbPage>
                        ) : (
                          <BreadcrumbLink href={crumb.href}>{crumb.label}</BreadcrumbLink>
                        )}
                      </BreadcrumbItem>
                    </Fragment>
                  )
                })}
              </BreadcrumbList>
            </Breadcrumb>
          ) : null}

          <div className="ml-auto flex items-center gap-2">{actions}</div>
        </header>

        <main className="flex-1 p-4 lg:p-6">{children}</main>
      </div>
    </div>
  )
}

export default AppShell01

import type { ReactNode } from 'react'
import { cn } from '../../lib/utils'

/**
 * Container primitive. Every block composes its own section from this so vertical
 * rhythm stays consistent across the catalog instead of being re-invented per block.
 */
export function Section({
  className,
  children,
  ...props
}: React.ComponentProps<'section'>) {
  return (
    <section
      className={cn('py-16 sm:py-24', className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-6xl px-6 lg:px-8">
        {children}
      </div>
    </section>
  )
}

/**
 * The six heading levels a block can be composed at.
 *
 * Every block takes a `headingLevel` prop typed with this and forwards it to the
 * one heading it renders, so the surrounding document decides where the block
 * sits in the outline rather than the block deciding for itself. `h2` is the
 * default because a block is composed, not a page.
 *
 * A block rendered where the document *already* owns a heading for the same
 * content passes one level deeper. A catalog card already names the block in its
 * own `h2`, so the copy of the block embedded inside that card passes `h3`: the
 * embedded heading then reads as a child of the card that introduces it instead
 * of as a second, competing sibling. This is a fact about where the block was
 * placed, not about the block, which is why it is a prop and not a default.
 */
export type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'

export function SectionHeading({
  eyebrow,
  title,
  as: Heading = 'h2',
  description,
  align = 'center',
  className,
}: {
  eyebrow?: ReactNode
  title: ReactNode
  description?: ReactNode
  align?: 'center' | 'left'
  /**
   * Heading level. Defaults to `h2` because blocks compose under a page heading.
   * A page that renders a block as its primary heading passes `as="h1"`; a
   * document with no `h1` gives screen-reader and search engines no top-level
   * entry point.
   */
  as?: HeadingLevel
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-4',
        align === 'center' ? 'items-center text-center' : 'items-start text-left',
        className,
      )}
    >
      {eyebrow ? (
        <span className="text-muted-foreground text-sm font-medium tracking-wide uppercase">
          {eyebrow}
        </span>
      ) : null}
      <Heading className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
        {title}
      </Heading>
      {description ? (
        <p className="text-muted-foreground max-w-2xl text-lg text-pretty">
          {description}
        </p>
      ) : null}
    </div>
  )
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
